 14	const maxBodyBytes = 1 << 20
 15	
 16	func (s *Server) createPayment(w http.ResponseWriter, r *http.Request) {
 17		var req createPaymentRequest
 18		if err := decodeJSON(r, &req); err != nil {
 19			writeError(w, err)
 20			return
 21		}
 22		amount, err := money.Parse(req.Amount, req.Currency)
 23		if err != nil {
 24			writeError(w, fmt.Errorf("amount: %w", err))
 25			return
 26		}
 27		in := payment.CreateInput{MerchantID: req.MerchantID, Amount: amount}
 28		s.idempotent(w, r, createFingerprint(in), func() (int, any) {
 29			p, err := s.svc.Create(r.Context(), in)
 30			if err != nil {
 31				return errorResponse(err)
 32			}
 33			return http.StatusCreated, toPaymentResponse(p)
 34		})
 35	}
 36	
 37	func (s *Server) getPayment(w http.ResponseWriter, r *http.Request) {
 38		p, err := s.svc.Get(r.Context(), r.PathValue("id"))
 39		if err != nil {
 40			writeError(w, err)
 41			return
 42		}
 43		writeJSON(w, http.StatusOK, toPaymentResponse(p))
 44	}
 45	
 46	func (s *Server) authorizePayment(w http.ResponseWriter, r *http.Request) {
 47		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Authorize(r.Context(), r.PathValue("id")) })
 48	}
 49	
 50	func (s *Server) capturePayment(w http.ResponseWriter, r *http.Request) {
 51		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Capture(r.Context(), r.PathValue("id")) })
 52	}
 53	
 54	func (s *Server) declinePayment(w http.ResponseWriter, r *http.Request) {
 55		var req declineRequest
 56		if r.ContentLength != 0 {
 57			if err := decodeJSON(r, &req); err != nil {
 58				writeError(w, err)
 59				return
 60			}
 61		}
 62		s.respondPayment(w, func() (payment.Payment, error) {
 63			return s.svc.Decline(r.Context(), r.PathValue("id"), req.Reason)
 64		})
 65	}
 66	
 67	func (s *Server) refundPayment(w http.ResponseWriter, r *http.Request) {
 68		id := r.PathValue("id")
 69		var req refundRequest
 70		if err := decodeJSON(r, &req); err != nil {
 71			writeError(w, err)
 72			return
 73		}
 74		p, err := s.svc.Get(r.Context(), id)
 75		if err != nil {
 76			writeError(w, err)
 77			return
 78		}
 79		amount, err := money.Parse(req.Amount, p.Amount.Currency.Code)
 80		if err != nil {
 81			writeError(w, fmt.Errorf("amount: %w", err))
 82			return
 83		}
 84		s.idempotent(w, r, refundFingerprint(id, amount), func() (int, any) {
 85			p, _, err := s.svc.Refund(r.Context(), id, amount)
 86			if err != nil {
 87				return errorResponse(err)
 88			}
 89			return http.StatusCreated, toPaymentResponse(p)
 90		})
 91	}
