 93	func (s *Server) listPayments(w http.ResponseWriter, r *http.Request) {
 94		q := r.URL.Query()
 95		page := payment.Page{Cursor: q.Get("cursor")}
 96		if v := q.Get("limit"); v != "" {
 97			n, err := strconv.Atoi(v)
 98			if err != nil {
 99				writeError(w, fmt.Errorf("%w: limit %q is not a number", payment.ErrInvalidInput, v))
100				return
101			}
102			page.Limit = n
103		}
104		ps, next, err := s.svc.List(r.Context(), r.PathValue("merchantID"), page)
105		if err != nil {
106			writeError(w, err)
107			return
108		}
109		out := listResponse{Data: make([]paymentResponse, 0, len(ps)), NextCursor: next}
110		for _, p := range ps {
111			out.Data = append(out.Data, toPaymentResponse(p))
112		}
113		writeJSON(w, http.StatusOK, out)
114	}
