type entry struct {
	rec  Record
	prev *entry
	next *entry
}

// Memory is an in-memory Store. Records expire TTL after Begin; a key is
// considered expired once now >= ExpiresAt.
type Memory struct {
	clock clock.Clock
	ttl   time.Duration

	mu      sync.Mutex
	records map[string]*entry
	head    *entry // oldest ExpiresAt
	tail    *entry // newest ExpiresAt
}

var _ Store = (*Memory)(nil)

// NewMemory returns a store whose records live for ttl.
func NewMemory(clk clock.Clock, ttl time.Duration) *Memory {
	return &Memory{clock: clk, ttl: ttl, records: make(map[string]*entry)}
}

// Begin implements Store.
func (m *Memory) Begin(_ context.Context, key, fingerprint string) (Record, bool, error) {
	if key == "" {
		return Record{}, false, ErrEmptyKey
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	now := m.clock.Now()
	m.purgeLocked(now)

	if e, ok := m.records[key]; ok {
		if now.Before(e.rec.ExpiresAt) {
			if e.rec.Fingerprint != fingerprint {
				return Record{}, false, fmt.Errorf("%w: key %q", ErrKeyReuse, key)
			}
			if !e.rec.Completed {
				return Record{}, false, fmt.Errorf("%w: key %q", ErrInProgress, key)
			}
			return copyRecord(&e.rec), false, nil
		}
		m.removeLocked(e)
	}
	e := &entry{
		rec: Record{
			Key:         key,
			Fingerprint: fingerprint,
			ExpiresAt:   now.Add(m.ttl),
		},
	}
	m.records[key] = e
	m.insertLocked(e)
	return copyRecord(&e.rec), true, nil
}

// Complete implements Store.
func (m *Memory) Complete(_ context.Context, key string, resp Response) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	e, ok := m.records[key]
	if !ok {
		return fmt.Errorf("%w: %q", ErrUnknownKey, key)
	}
	e.rec.Completed = true
	e.rec.Response = Response{Status: resp.Status, Body: append([]byte(nil), resp.Body...)}
	return nil
}

// Release implements Store.
func (m *Memory) Release(_ context.Context, key string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	e, ok := m.records[key]
	if !ok {
		return fmt.Errorf("%w: %q", ErrUnknownKey, key)
	}
	m.removeLocked(e)
	return nil
}

// Len returns the number of records currently held (expired ones included
// until the next purge).
func (m *Memory) Len() int {
	m.mu.Lock()
	defer m.mu.Unlock()
	return len(m.records)
}

// purgeLocked evicts expired records, oldest first.
func (m *Memory) purgeLocked(now time.Time) {
	for m.head != nil && !now.Before(m.head.rec.ExpiresAt) {
		m.removeLocked(m.head)
	}
}

func (m *Memory) insertLocked(e *entry) {
	if m.tail == nil {
		m.head = e
		m.tail = e
		return
	}
	if !e.rec.ExpiresAt.Before(m.tail.rec.ExpiresAt) {
		e.prev = m.tail
		m.tail.next = e
		m.tail = e
		return
	}
	cur := m.tail
	for cur != nil && e.rec.ExpiresAt.Before(cur.rec.ExpiresAt) {
		cur = cur.prev
	}
	if cur == nil {
		e.next = m.head
		m.head.prev = e
		m.head = e
		return
	}
	e.prev = cur
	e.next = cur.next
	cur.next.prev = e
	cur.next = e
}

func (m *Memory) removeLocked(e *entry) {
	if e.prev != nil {
		e.prev.next = e.next
	} else {
		m.head = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	} else {
		m.tail = e.prev
	}
	e.prev = nil
	e.next = nil
	delete(m.records, e.rec.Key)
}

func copyRecord(r *Record) Record {
	c := *r
	c.Response.Body = append([]byte(nil), r.Response.Body...)
	return c
}

