	m.records[key] = r
	return copyRecord(r), true, nil
}

// Complete implements Store.
func (m *Memory) Complete(_ context.Context, key string, resp Response) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	r, ok := m.records[key]
	if !ok {
		return fmt.Errorf("%w: %q", ErrUnknownKey, key)
	}
	r.Completed = true
	r.Response = Response{Status: resp.Status, Body: append([]byte(nil), resp.Body...)}
	return nil
}

// Release implements Store.
func (m *Memory) Release(_ context.Context, key string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, ok := m.records[key]; !ok {
		return fmt.Errorf("%w: %q", ErrUnknownKey, key)
	}
	delete(m.records, key)
	return nil
}

// Len returns the number of records currently held (expired ones included
// until the next purge).
func (m *Memory) Len() int {
	m.mu.Lock()
	defer m.mu.Unlock()
	return len(m.records)
}

// purgeLocked evicts expired records, oldest first.
func (m *Memory) purgeLocked(now time.Time) {
	recs := make([]*Record, 0, len(m.records))
	for _, r := range m.records {
		recs = append(recs, r)
	}
	sort.Slice(recs, func(i, j int) bool { return recs[i].ExpiresAt.Before(recs[j].ExpiresAt) })
	for _, r := range recs {
		if now.Before(r.ExpiresAt) {
			break
		}
		delete(m.records, r.Key)
	}
}

func copyRecord(r *Record) Record {
	c := *r
	c.Response.Body = append([]byte(nil), r.Response.Body...)
	return c
}

