	rec, started, err := s.Begin(ctx, "k1", "fp1")
	if err != nil || started || string(rec.Response.Body) != "one" {
		t.Fatalf("before expiry: started=%v err=%v body=%q", started, err, rec.Response.Body)
	}

	// At exact ExpiresAt (now >= ExpiresAt): expired, never replayed, can reuse with new fingerprint.
	clk.Advance(time.Nanosecond)
	_, started, err = s.Begin(ctx, "k1", "fp2")
	if err != nil || !started {
		t.Fatalf("at expiry: started=%v err=%v", started, err)
	}
	if s.Len() != 1 {
		t.Fatalf("Len = %d, want 1", s.Len())
	}

	// Evicts batches of expired keys while keeping live ones.
	for i := 0; i < 100; i++ {
		if _, _, err := s.Begin(ctx, fmt.Sprintf("old-%d", i), "fp"); err != nil {
			t.Fatal(err)
		}
	}
	clk.Advance(12 * time.Hour)
	for i := 0; i < 50; i++ {
		if _, _, err := s.Begin(ctx, fmt.Sprintf("live-%d", i), "fp"); err != nil {
			t.Fatal(err)
		}
	}
	// Advance another 12h: k1 and old-0..99 are at 24h (expired), live-0..49 are at 12h (live).
	clk.Advance(12 * time.Hour)
	if _, started, err := s.Begin(ctx, "trigger", "fp"); err != nil || !started {
		t.Fatalf("trigger Begin: started=%v err=%v", started, err)
	}
	if got := s.Len(); got != 51 {
		t.Fatalf("Len after purge = %d, want 51", got)
	}
}

func TestReleaseDoesNotCorruptExpiryQueue(t *testing.T) {
	ctx := context.Background()
	s, clk := newStore()

	// Insert 3 keys at t=0, t=1h, t=2h; release head, middle, tail in turn, and re-begin released key.
	for i, k := range []string{"a", "b", "c"} {
		if i > 0 {
			clk.Advance(time.Hour)
		}
		if _, _, err := s.Begin(ctx, k, "fp"); err != nil {
			t.Fatal(err)
		}
	}
	// Release middle ("b"), then re-insert "b" at t=10h so its new expiry is t=34h (not t=25h).
	if err := s.Release(ctx, "b"); err != nil {
		t.Fatal(err)
	}
	clk.Advance(8 * time.Hour) // now t=10h
	if _, started, err := s.Begin(ctx, "b", "fp-new"); err != nil || !started {
		t.Fatalf("re-begin b: started=%v err=%v", started, err)
	}
	if err := s.Complete(ctx, "b", Response{Status: 200, Body: []byte("ok")}); err != nil {
		t.Fatal(err)
	}
	// Release head ("a") and tail... wait: "c" is at t=2h, "b" is now tail at t=10h.
	if err := s.Release(ctx, "a"); err != nil {
		t.Fatal(err)
	}

	// Advance to t=26h: "c" (t=2h + 24h = 26h) expires, "b" (t=10h + 24h = 34h) must still be live!
	clk.Advance(16 * time.Hour)
	rec, started, err := s.Begin(ctx, "b", "fp-new")
	if err != nil || started || string(rec.Response.Body) != "ok" {
		t.Fatalf("b at t=26h: started=%v err=%v body=%q", started, err, rec.Response.Body)
	}
	if got := s.Len(); got != 1 {
		t.Fatalf("Len = %d, want 1", got)
	}
}

func TestOutOfOrderClockMaintainsExpiryOrder(t *testing.T) {
	ctx := context.Background()
	s, clk := newStore()

	_, _, _ = s.Begin(ctx, "late", "fp")  // expires t+24h
	clk.Advance(-2 * time.Hour)           // clock moves backwards
	_, _, _ = s.Begin(ctx, "early", "fp") // expires t+22h
	clk.Advance(time.Hour)                // clock in middle
	_, _, _ = s.Begin(ctx, "mid", "fp")   // expires t+23h

	// Advance to t+22h: "early" expires, "mid" and "late" stay.
	clk.Advance(23 * time.Hour)
	_, _, _ = s.Begin(ctx, "probe1", "fp")
	if got := s.Len(); got != 3 { // mid, late, probe1
		t.Fatalf("Len = %d, want 3", got)
	}
	// Verify "early" is treated as new.
	if _, started, err := s.Begin(ctx, "early", "other"); err != nil || !started {
		t.Fatalf("early should have expired: started=%v err=%v", started, err)
	}
}

func TestBeginLatencyWithManyLiveKeys(t *testing.T) {
	ctx := context.Background()
	s, clk := newStore()

	const liveKeys = 50_000
	resp := Response{Status: 201, Body: []byte(`{"id":"pay_1"}`)}
	for i := 0; i < liveKeys; i++ {
		k := "live-" + strconv.Itoa(i)
		if _, _, err := s.Begin(ctx, k, "fp"); err != nil {
			t.Fatal(err)
		}
		if err := s.Complete(ctx, k, resp); err != nil {
			t.Fatal(err)
		}
		clk.Advance(10 * time.Millisecond)
	}

	const probes = 2_000
	start := time.Now()
	for i := 0; i < probes; i++ {
		clk.Advance(100 * time.Millisecond)
		k := "probe-" + strconv.Itoa(i)
		if _, started, err := s.Begin(ctx, k, "fp"); err != nil || !started {
			t.Fatalf("Begin %s: started=%v err=%v", k, started, err)
		}
		// Also test replay on an existing key.
		if _, started, err := s.Begin(ctx, "live-0", "fp"); err != nil || started {
			t.Fatalf("replay live-0: started=%v err=%v", started, err)
		}
	}
	avg := time.Since(start) / (2 * probes)
	t.Logf("avg Begin with %d live keys: %v", liveKeys, avg)
	if avg > 50*time.Microsecond {
		t.Fatalf("Begin too slow with %d live keys: avg %v", liveKeys, avg)
	}
}

func TestConcurrentAccess(t *testing.T) {
	ctx := context.Background()
	s, clk := newStore()

	var wg sync.WaitGroup
	for g := 0; g < 8; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for i := 0; i < 200; i++ {
				k := fmt.Sprintf("g%d-%d", g, i)
				if _, started, err := s.Begin(ctx, k, "fp"); err != nil || !started {
					t.Errorf("Begin %s: started=%v err=%v", k, started, err)
					return
				}
				if i%3 == 0 {
					_ = s.Release(ctx, k)
				} else {
					_ = s.Complete(ctx, k, Response{Status: 200, Body: []byte("ok")})
					_, _, _ = s.Begin(ctx, k, "fp")
				}
				if i%20 == 0 {
					clk.Advance(time.Hour)
					_ = s.Len()
				}
			}
		}(g)
	}
	wg.Wait()
}

