 15	
 16	var (
 17		// ErrInProgress means another request with the same key has not finished yet.
 18		ErrInProgress = errors.New("request with this idempotency key is still in progress")
 19		// ErrKeyReuse means the key was already used for a different request.
 20		ErrKeyReuse = errors.New("idempotency key reused with a different request")
 21		// ErrUnknownKey is returned when completing or releasing a key that was never begun.
 22		ErrUnknownKey = errors.New("unknown idempotency key")
 23		// ErrEmptyKey is returned for an empty key.
 24		ErrEmptyKey = errors.New("empty idempotency key")
 25	)
 26	
 27	// Response is the stored outcome replayed to retries.
 28	type Response struct {
 29		Status int
 30		Body   []byte
 31	}
 32	
 33	// Record is the state of one key.
 34	type Record struct {
 35		Key         string
 36		Fingerprint string
 37		Completed   bool
 38		Response    Response
 39		ExpiresAt   time.Time
 40	}
 41	
 42	// Store is the idempotency contract.
 43	type Store interface {
 44		// Begin reserves key for a request identified by fingerprint. started is
 45		// true when the caller must execute the request and then call Complete or
 46		// Release. When started is false and err is nil, rec holds the stored
 47		// response to replay.
 48		Begin(ctx context.Context, key, fingerprint string) (rec Record, started bool, err error)
 49		Complete(ctx context.Context, key string, resp Response) error
 50		// Release forgets a key whose request failed so it can be retried.
 51		Release(ctx context.Context, key string) error
 52	}
 53	
 54	type entry struct {
 55		rec  Record
 56		prev *entry
 57		next *entry
 58	}
 59	
 60	// Memory is an in-memory Store. Records expire TTL after Begin; a key is
 61	// considered expired once now >= ExpiresAt.
 62	type Memory struct {
 63		clock clock.Clock
 64		ttl   time.Duration
 65	
 66		mu      sync.Mutex
 67		records map[string]*entry
 68		head    *entry // oldest ExpiresAt
 69		tail    *entry // newest ExpiresAt
 70	}
 71	
 72	var _ Store = (*Memory)(nil)
 73	
 74	// NewMemory returns a store whose records live for ttl.
 75	func NewMemory(clk clock.Clock, ttl time.Duration) *Memory {
 76		return &Memory{clock: clk, ttl: ttl, records: make(map[string]*entry)}
 77	}
 78	
 79	// Begin implements Store.
 80	func (m *Memory) Begin(_ context.Context, key, fingerprint string) (Record, bool, error) {
 81		if key == "" {
 82			return Record{}, false, ErrEmptyKey
 83		}
 84		m.mu.Lock()
 85		defer m.mu.Unlock()
 86		now := m.clock.Now()
 87		m.purgeLocked(now)
 88	
 89		if e, ok := m.records[key]; ok {
 90			if now.Before(e.rec.ExpiresAt) {
 91				if e.rec.Fingerprint != fingerprint {
 92					return Record{}, false, fmt.Errorf("%w: key %q", ErrKeyReuse, key)
 93				}
 94				if !e.rec.Completed {
 95					return Record{}, false, fmt.Errorf("%w: key %q", ErrInProgress, key)
 96				}
 97				return copyRecord(&e.rec), false, nil
 98			}
 99			m.removeLocked(e)
100		}
101		e := &entry{
102			rec: Record{
103				Key:         key,
104				Fingerprint: fingerprint,
105				ExpiresAt:   now.Add(m.ttl),
106			},
107		}
108		m.records[key] = e
109		m.insertLocked(e)
110		return copyRecord(&e.rec), true, nil
111	}
112	
113	// Complete implements Store.
114	func (m *Memory) Complete(_ context.Context, key string, resp Response) error {
115		m.mu.Lock()
116		defer m.mu.Unlock()
117		e, ok := m.records[key]
118		if !ok {
119			return fmt.Errorf("%w: %q", ErrUnknownKey, key)
120		}
121		e.rec.Completed = true
122		e.rec.Response = Response{Status: resp.Status, Body: append([]byte(nil), resp.Body...)}
123		return nil
124	}
125	
126	// Release implements Store.
127	func (m *Memory) Release(_ context.Context, key string) error {
128		m.mu.Lock()
129		defer m.mu.Unlock()
130		e, ok := m.records[key]
131		if !ok {
132			return fmt.Errorf("%w: %q", ErrUnknownKey, key)
133		}
134		m.removeLocked(e)
135		return nil
136	}
137	
138	// Len returns the number of records currently held (expired ones included
139	// until the next purge).
140	func (m *Memory) Len() int {
141		m.mu.Lock()
142		defer m.mu.Unlock()
143		return len(m.records)
144	}
145	
146	// purgeLocked evicts expired records, oldest first.
147	func (m *Memory) purgeLocked(now time.Time) {
148		for m.head != nil && !now.Before(m.head.rec.ExpiresAt) {
149			m.removeLocked(m.head)
150		}
151	}
152	
153	func (m *Memory) insertLocked(e *entry) {
154		if m.tail == nil {
155			m.head = e
156			m.tail = e
157			return
158		}
159		if !e.rec.ExpiresAt.Before(m.tail.rec.ExpiresAt) {
160			e.prev = m.tail
161			m.tail.next = e
162			m.tail = e
163			return
164		}
165		cur := m.tail
166		for cur != nil && e.rec.ExpiresAt.Before(cur.rec.ExpiresAt) {
167			cur = cur.prev
168		}
169		if cur == nil {
170			e.next = m.head
171			m.head.prev = e
172			m.head = e
173			return
174		}
175		e.prev = cur
176		e.next = cur.next
177		cur.next.prev = e
178		cur.next = e
179	}
180	
181	func (m *Memory) removeLocked(e *entry) {
182		if e.prev != nil {
183			e.prev.next = e.next
184		} else {
185			m.head = e.next
186		}
187		if e.next != nil {
188			e.next.prev = e.prev
189		} else {
190			m.tail = e.prev
191		}
192		e.prev = nil
193		e.next = nil
194		delete(m.records, e.rec.Key)
195	}
196	
197	func copyRecord(r *Record) Record {
198		c := *r
199		c.Response.Body = append([]byte(nil), r.Response.Body...)
200		return c
201	}

