 20	func TestBeginCompleteReplay(t *testing.T) {
 21		ctx := context.Background()
 22		s, _ := newStore()
 23		_, started, err := s.Begin(ctx, "k1", "fp")
 24		if err != nil || !started {
 25			t.Fatalf("first Begin: started=%v err=%v", started, err)
 26		}
 27		if err := s.Complete(ctx, "k1", Response{Status: 201, Body: []byte(`{"id":"x"}`)}); err != nil {
 28			t.Fatal(err)
 29		}
 30		rec, started, err := s.Begin(ctx, "k1", "fp")
 31		if err != nil || started {
 32			t.Fatalf("replay Begin: started=%v err=%v", started, err)
 33		}
 34		if rec.Response.Status != 201 || string(rec.Response.Body) != `{"id":"x"}` {
 35			t.Fatalf("replayed %+v", rec.Response)
 36		}
 37	}
