 39	func TestBeginErrors(t *testing.T) {
 40		ctx := context.Background()
 41		tests := []struct {
 42			name    string
 43			prep    func(s *Memory)
 44			fp      string
 45			wantErr error
 46		}{
 47			{"in progress", func(s *Memory) { _, _, _ = s.Begin(ctx, "k", "fp") }, "fp", ErrInProgress},
 48			{"different request", func(s *Memory) {
 49				_, _, _ = s.Begin(ctx, "k", "fp")
 50				_ = s.Complete(ctx, "k", Response{Status: 200})
 51			}, "other", ErrKeyReuse},
 52		}
 53		for _, tt := range tests {
 54			t.Run(tt.name, func(t *testing.T) {
 55				s, _ := newStore()
 56				tt.prep(s)
 57				if _, _, err := s.Begin(ctx, "k", tt.fp); !errors.Is(err, tt.wantErr) {
 58					t.Fatalf("err = %v, want %v", err, tt.wantErr)
 59				}
 60			})
 61		}
 62		s, _ := newStore()
 63		if _, _, err := s.Begin(ctx, "", "fp"); !errors.Is(err, ErrEmptyKey) {
 64			t.Fatalf("empty key: %v", err)
 65		}
