 96	func TestExpiryAndEviction(t *testing.T) {
 97		ctx := context.Background()
 98		s, clk := newStore() // ttl = 24h
 99	
100		if _, started, err := s.Begin(ctx, "k1", "fp1"); err != nil || !started {
101			t.Fatalf("first Begin: started=%v err=%v", started, err)
102		}
103		if err := s.Complete(ctx, "k1", Response{Status: 201, Body: []byte("one")}); err != nil {
104			t.Fatal(err)
105		}
106	
107		// Just before expiry: still live and replayed.
108		clk.Advance(24*time.Hour - time.Nanosecond)
109		rec, started, err := s.Begin(ctx, "k1", "fp1")
110		if err != nil || started || string(rec.Response.Body) != "one" {
111			t.Fatalf("before expiry: started=%v err=%v body=%q", started, err, rec.Response.Body)
112		}
113	
114		// At exact ExpiresAt (now >= ExpiresAt): expired, never replayed, can reuse with new fingerprint.
115		clk.Advance(time.Nanosecond)
116		_, started, err = s.Begin(ctx, "k1", "fp2")
117		if err != nil || !started {
118			t.Fatalf("at expiry: started=%v err=%v", started, err)
119		}
120		if s.Len() != 1 {
121			t.Fatalf("Len = %d, want 1", s.Len())
122		}
123	
124		// Evicts batches of expired keys while keeping live ones.
125		for i := 0; i < 100; i++ {
126			if _, _, err := s.Begin(ctx, fmt.Sprintf("old-%d", i), "fp"); err != nil {
127				t.Fatal(err)
128			}
129		}
130		clk.Advance(12 * time.Hour)
131		for i := 0; i < 50; i++ {
132			if _, _, err := s.Begin(ctx, fmt.Sprintf("live-%d", i), "fp"); err != nil {
133				t.Fatal(err)
134			}
135		}
136		// Advance another 12h: k1 and old-0..99 are at 24h (expired), live-0..49 are at 12h (live).
137		clk.Advance(12 * time.Hour)
138		if _, started, err := s.Begin(ctx, "trigger", "fp"); err != nil || !started {
139			t.Fatalf("trigger Begin: started=%v err=%v", started, err)
140		}
141		if got := s.Len(); got != 51 {
142			t.Fatalf("Len after purge = %d, want 51", got)
143		}
144	}
