146	func TestReleaseDoesNotCorruptExpiryQueue(t *testing.T) {
147		ctx := context.Background()
148		s, clk := newStore()
149	
150		// Insert 3 keys at t=0, t=1h, t=2h; release head, middle, tail in turn, and re-begin released key.
151		for i, k := range []string{"a", "b", "c"} {
152			if i > 0 {
153				clk.Advance(time.Hour)
154			}
155			if _, _, err := s.Begin(ctx, k, "fp"); err != nil {
156				t.Fatal(err)
157			}
158		}
159		// Release middle ("b"), then re-insert "b" at t=10h so its new expiry is t=34h (not t=25h).
160		if err := s.Release(ctx, "b"); err != nil {
161			t.Fatal(err)
162		}
163		clk.Advance(8 * time.Hour) // now t=10h
164		if _, started, err := s.Begin(ctx, "b", "fp-new"); err != nil || !started {
165			t.Fatalf("re-begin b: started=%v err=%v", started, err)
166		}
167		if err := s.Complete(ctx, "b", Response{Status: 200, Body: []byte("ok")}); err != nil {
168			t.Fatal(err)
169		}
170		// Release head ("a") and tail... wait: "c" is at t=2h, "b" is now tail at t=10h.
171		if err := s.Release(ctx, "a"); err != nil {
172			t.Fatal(err)
173		}
174	
175		// Advance to t=26h: "c" (t=2h + 24h = 26h) expires, "b" (t=10h + 24h = 34h) must still be live!
176		clk.Advance(16 * time.Hour)
177		rec, started, err := s.Begin(ctx, "b", "fp-new")
178		if err != nil || started || string(rec.Response.Body) != "ok" {
179			t.Fatalf("b at t=26h: started=%v err=%v body=%q", started, err, rec.Response.Body)
180		}
181		if got := s.Len(); got != 1 {
182			t.Fatalf("Len = %d, want 1", got)
183		}
184	}
