186	func TestOutOfOrderClockMaintainsExpiryOrder(t *testing.T) {
187		ctx := context.Background()
188		s, clk := newStore()
189	
190		_, _, _ = s.Begin(ctx, "late", "fp")  // expires t+24h
191		clk.Advance(-2 * time.Hour)           // clock moves backwards
192		_, _, _ = s.Begin(ctx, "early", "fp") // expires t+22h
193		clk.Advance(time.Hour)                // clock in middle
194		_, _, _ = s.Begin(ctx, "mid", "fp")   // expires t+23h
195	
196		// Advance to t+22h: "early" expires, "mid" and "late" stay.
197		clk.Advance(23 * time.Hour)
198		_, _, _ = s.Begin(ctx, "probe1", "fp")
199		if got := s.Len(); got != 3 { // mid, late, probe1
200			t.Fatalf("Len = %d, want 3", got)
201		}
202		// Verify "early" is treated as new.
203		if _, started, err := s.Begin(ctx, "early", "other"); err != nil || !started {
204			t.Fatalf("early should have expired: started=%v err=%v", started, err)
205		}
206	}
