208	func TestBeginLatencyWithManyLiveKeys(t *testing.T) {
209		ctx := context.Background()
210		s, clk := newStore()
211	
212		const liveKeys = 50_000
213		resp := Response{Status: 201, Body: []byte(`{"id":"pay_1"}`)}
214		for i := 0; i < liveKeys; i++ {
215			k := "live-" + strconv.Itoa(i)
216			if _, _, err := s.Begin(ctx, k, "fp"); err != nil {
217				t.Fatal(err)
218			}
219			if err := s.Complete(ctx, k, resp); err != nil {
220				t.Fatal(err)
221			}
222			clk.Advance(10 * time.Millisecond)
223		}
224	
225		const probes = 2_000
226		start := time.Now()
227		for i := 0; i < probes; i++ {
228			clk.Advance(100 * time.Millisecond)
229			k := "probe-" + strconv.Itoa(i)
230			if _, started, err := s.Begin(ctx, k, "fp"); err != nil || !started {
231				t.Fatalf("Begin %s: started=%v err=%v", k, started, err)
232			}
233			// Also test replay on an existing key.
234			if _, started, err := s.Begin(ctx, "live-0", "fp"); err != nil || started {
235				t.Fatalf("replay live-0: started=%v err=%v", started, err)
236			}
237		}
238		avg := time.Since(start) / (2 * probes)
239		t.Logf("avg Begin with %d live keys: %v", liveKeys, avg)
240		if avg > 50*time.Microsecond {
241			t.Fatalf("Begin too slow with %d live keys: avg %v", liveKeys, avg)
242		}
