245	func TestConcurrentAccess(t *testing.T) {
246		ctx := context.Background()
247		s, clk := newStore()
248	
249		var wg sync.WaitGroup
250		for g := 0; g < 8; g++ {
251			wg.Add(1)
252			go func(g int) {
253				defer wg.Done()
254				for i := 0; i < 200; i++ {
255					k := fmt.Sprintf("g%d-%d", g, i)
256					if _, started, err := s.Begin(ctx, k, "fp"); err != nil || !started {
257						t.Errorf("Begin %s: started=%v err=%v", k, started, err)
258						return
259					}
260					if i%3 == 0 {
261						_ = s.Release(ctx, k)
262					} else {
263						_ = s.Complete(ctx, k, Response{Status: 200, Body: []byte("ok")})
264						_, _, _ = s.Begin(ctx, k, "fp")
265					}
266					if i%20 == 0 {
267						clk.Advance(time.Hour)
268						_ = s.Len()
269					}
270				}
271			}(g)
272		}
273		wg.Wait()
274	}

